UPDATE cms_pages SET title='Avocado Hass',summary='Собственное ПО для защиты вашей инфраструктуры',body='Avocado Hass — наш программный продукт для защиты трафика, противодействия DDoS и поддержания доступности сервисов. Развиваем управление защитой и аналитику в едином интерфейсе.

Обсудим вашу инфраструктуру, задачи и условия подключения в чате.',updated_at=1789214400000 WHERE slug='hass' AND status='published' AND title='Avocado Hass' AND summary='Ваш трафик под защитой' AND replace(body,char(13),'')='Защита от DDoS-атак и блокировок РКН. Стабильность сервисов, глобальная сеть и аналитика.

Обсудим вашу инфраструктуру и условия подключения в чате.';
UPDATE cms_pages SET title='Avocado Ettinger',summary='Собственное ПО для автоматизации операций',body='Avocado Ettinger — наш программный продукт для оркестрации инфраструктуры и автоматизации повторяющихся операций. Массовые задачи, ИИ-адаптеры и инструменты управления для вашей команды.

Домены и серверы доступны как дополнительные услуги Avocado. Подберём конфигурацию и согласуем условия в чате.',updated_at=1789214400000 WHERE slug='ettinger' AND status='published' AND title='Avocado Ettinger' AND summary='Офисная оркестрация нового поколения' AND replace(body,char(13),'')='Массовая закупка доменов и серверов. ИИ-адаптеры. Автоматизация NIC.RU. Регистрация и верификация аккаунтов.

Автоматизируйте повторяющиеся операции и управляйте инфраструктурой в одной экосистеме.';
UPDATE cms_pages SET title='Разрабатываем ПО. Защищаем ваши возможности.',summary='Avocado — команда разработчиков. Создаём собственные продукты Hass и Ettinger, автоматизацию и решения под вашу задачу. Домены, серверы и прокси дополняют наше ПО.',body='Собственное ПО и разработка на заказ. Обсуждаем задачи конфиденциально, запрашиваем только необходимые для работы данные. Принимаем оплату криптовалютой.',updated_at=1789214400000 WHERE slug='home' AND status='published' AND title='Инфраструктура, которая работает на вас.' AND summary='Защита, автоматизация и масштабирование в одной экосистеме.' AND replace(body,char(13),'')='Avocado объединяет защиту трафика, анти-DDoS, защиту от блокировок РКН, массовую закупку доменов и серверов, ИИ-адаптеры и автоматизацию NIC.RU.';
UPDATE cms_pages SET title='Инфраструктура для вашего ПО',summary='Домены, серверы и прокси дополняют программные продукты Avocado.',body='Домены, серверы и прокси Avocado для ваших проектов. В каталоге указаны ориентировочные цены для предварительного расчёта. Наличие, географию, конфигурацию и итоговую сумму подтвердим в чате перед счётом.

Стоимость регистрации и продления доменного имени согласуется до оплаты.',updated_at=1789214400000 WHERE slug='catalog' AND status='published' AND title='Инфраструктура под вашу задачу' AND summary='Домены, серверы и прокси. Подберём конфигурацию и согласуем условия в чате.' AND replace(body,char(13),'')='Выберите направление. Страна, наличие и итоговая стоимость подтверждаются оператором перед выставлением счёта.';
UPDATE cms_pages SET title='География инфраструктуры',summary='Локации для ваших проектов.',body='Подберём страну размещения и ресурсы под задачи вашего проекта. Наличие нужной услуги, конкретную локацию и конфигурацию подтвердим в чате.

Доступность выбранного типа прокси в каждой стране уточняется отдельно.',updated_at=1789214400000 WHERE slug='countries' AND status='published' AND title='География вашей инфраструктуры' AND summary='Нужная локация для вашего проекта.' AND replace(body,char(13),'')='Уточните страну и требования в чате. Мы проверим доступность и предложим подходящую конфигурацию.';
UPDATE cms_pages SET title='Оплата криптовалютой',summary='Криптооплата без KYC со стороны Avocado.',body='Согласуйте с оператором услугу, сумму, криптовалюту и сеть. Для оплаты Avocado не запрашивает документы для верификации личности; передавайте только данные, необходимые для выполнения заявки.

Получите счёт с адресом кошелька и точной суммой. Переведите средства в указанной сети и сообщите идентификатор транзакции в чате. После ручного подтверждения оплаты согласуем выдачу услуги или следующий этап разработки.

Условия конкретной услуги и сроки уточняем до выставления счёта.',updated_at=1789214400000 WHERE slug='payment' AND status='published' AND title='Оплата криптовалютой' AND summary='Без KYC и верификаций. Согласуйте удобную валюту и сеть в чате.' AND replace(body,char(13),'')='Обсудите услугу с оператором. Получите счёт с точной суммой, сетью и адресом кошелька. Переведите средства по реквизитам счёта и отправьте идентификатор транзакции в чат. После ручного подтверждения поступления мы выдадим услугу.

Поддержку выбранной криптовалюты и сети подтвердим перед оплатой. Сроки выдачи и условия согласуем до выставления счёта.';
UPDATE cms_pages SET title='Домены',summary='Поиск, регистрация и массовая закупка доменов.',body='Домены Avocado для ваших проектов. Указана ориентировочная стоимость первого года. Доступность имени, точную цену регистрации и продления подтвердим в чате перед счётом.',updated_at=1789214400000 WHERE slug='category-domains' AND status='published' AND title='Домены' AND summary='Поиск, регистрация и массовая закупка доменов.' AND replace(body,char(13),'')='Расскажите о требованиях, географии и нагрузке. Подберём решение, проверим наличие и согласуем стоимость.';
UPDATE cms_pages SET title='VPS',summary='Виртуальные серверы под задачи вашего проекта.',body='Виртуальные серверы Avocado для вашего ПО. Ориентировочные цены помогут оценить бюджет. Конфигурацию, локацию, наличие и итоговую стоимость проверим перед счётом.',updated_at=1789214400000 WHERE slug='category-vps' AND status='published' AND title='VPS' AND summary='Виртуальные серверы под задачи вашего проекта.' AND replace(body,char(13),'')='Расскажите о требованиях, географии и нагрузке. Подберём решение, проверим наличие и согласуем стоимость.';
UPDATE cms_pages SET title='Выделенные серверы',summary='Физические серверы с индивидуальной конфигурацией.',body='Выделенные серверы Avocado под задачи вашего проекта. Указаны ориентировочные цены. Проверьте минимальный срок аренды в карточке; наличие и итоговую сумму подтвердим в чате.',updated_at=1789214400000 WHERE slug='category-dedicated' AND status='published' AND title='Выделенные серверы' AND summary='Физические серверы с индивидуальной конфигурацией.' AND replace(body,char(13),'')='Расскажите о требованиях, географии и нагрузке. Подберём решение, проверим наличие и согласуем стоимость.';
UPDATE cms_pages SET title='Прокси',summary='Подбор прокси под географию и требования проекта.',body='Прокси Avocado для ваших задач. Ориентировочная цена указана за один IP на 30 дней с учётом диапазона количества. Тип прокси, страну, наличие и итоговую стоимость согласуем в чате.',updated_at=1789214400000 WHERE slug='category-proxies' AND status='published' AND title='Прокси' AND summary='Подбор прокси под географию и требования проекта.' AND replace(body,char(13),'')='Расскажите о требованиях, географии и нагрузке. Подберём решение, проверим наличие и согласуем стоимость.';
INSERT OR IGNORE INTO cms_pages(slug,title,summary,body,status,created_at,updated_at) VALUES('software','Разработка ПО под вашу задачу','От идеи и архитектуры до работающего продукта.','Разрабатываем веб-приложения, внутренние инструменты и автоматизацию для бизнеса. Изучим задачу, предложим техническое решение и согласуем этапы, сроки и стоимость.

Собственные продукты Avocado Hass и Ettinger развиваем вместе с решениями на заказ. Инфраструктуру для проекта — домены, серверы и прокси — можно подобрать дополнительно.

Расскажите о задаче в чате. Обсуждение конфиденциально; для начала достаточно описания проекта.','published',1789214400000,1789214400000);
